export default function MateriauList({ materiaux }) {
    if (!materiaux || materiaux.length === 0) {
        return <div className="bg-white p-4 rounded-xl shadow text-gray-500">Aucun matériau calculé</div>;
    }

    return (
        <div className="bg-white p-4 rounded-xl shadow">
            <h2 className="font-bold mb-3">🧱 Liste des matériaux</h2>
            <table className="w-full text-sm">
                <thead>
                <tr className="bg-gray-200">
                    <th className="p-2 text-left">Matériau</th>
                    <th className="p-2 text-left">Quantité</th>
                    <th className="p-2 text-left">Coût (DH)</th>
                </tr>
                </thead>
                <tbody>
                {materiaux.map((m, i) => (
                    <tr key={i} className="border-b">
                        <td className="p-2">{m.nom}</td>
                        <td className="p-2">{m.quantite}</td>
                        <td className="p-2 font-semibold">{m.cout}</td>
                    </tr>
                ))}
                </tbody>
            </table>
        </div>
    );
}
